# This code has been fully generated by an AI.
"""HP-Regeln: Ringout, Kollision, Hindernisse, Power-ups, Sieg. Reine Logik ohne Bild."""

import itertools
import random
from dataclasses import dataclass, field

import cv2
import numpy as np

from .config import Settings


@dataclass
class RobotInput:
    id: int
    present: bool
    pos: np.ndarray
    vel: np.ndarray
    radius: float
    inside: float
    # Umriss in Arena-Einheiten; nur vorhanden, solange der Roboter gesehen wird.
    outline: np.ndarray | None


def touches(outline: np.ndarray, point: np.ndarray, radius: float) -> bool:
    # Der Umriss statt eines Kreises, damit ein Gegenstand schon beim ersten Pixel Berührung zählt.
    poly = outline.reshape(-1, 1, 2).astype(np.float32)
    return cv2.pointPolygonTest(poly, (float(point[0]), float(point[1])), True) >= -radius


@dataclass
class Item:
    id: int
    kind: str
    pos: np.ndarray
    radius: float
    born: float
    expires: float
    armed_at: float

    def armed(self, t: float) -> bool:
        return t >= self.armed_at


@dataclass
class Player:
    id: int
    name: str
    hp: float
    outside_since: float | None = None
    last_vel: np.ndarray = field(default_factory=lambda: np.zeros(2, np.float32))
    last_pos: np.ndarray | None = None


class Game:
    def __init__(
        self, cfg: Settings, players: list[tuple[int, str]], t: float, rng: random.Random | None = None
    ):
        self.cfg = cfg
        self.rng = rng or random.Random()
        self.players = [Player(pid, name, cfg.start_hp) for pid, name in players]
        self.items: list[Item] = []
        self.events: list[dict] = []
        self.finished = False
        self.winner: int | None = None
        self._ids = itertools.count(1)
        self._event_ids = itertools.count(1)
        self._last_t = t
        self._prev_contact = False
        self._last_collision = -1e9
        self._next_spawn = {
            "obstacle": t + self._interval(cfg.obstacle_interval_s),
            "powerup": t + self._interval(cfg.powerup_interval_s),
        }

    def player(self, pid: int) -> Player:
        return next(p for p in self.players if p.id == pid)

    def _interval(self, base: float) -> float:
        return base * self.rng.uniform(0.7, 1.3)

    def _event(self, t: float, event_type: str, **data) -> None:
        self.events.append({"id": next(self._event_ids), "t": t, "type": event_type, **data})
        del self.events[:-30]

    def _damage(self, t: float, p: Player, amount: float, kind: str, pos: np.ndarray | None) -> None:
        if amount <= 0:
            return
        p.hp = max(0.0, p.hp - amount)
        if kind != "ringout":
            where = None if pos is None else pos.tolist()
            self._event(t, kind, player=p.id, amount=round(amount, 1), pos=where)

    def tick(self, t: float, robots: list[RobotInput], contact: bool) -> None:
        if self.finished:
            return
        dt = max(0.0, t - self._last_t)
        self._last_t = t
        by_id = {r.id: r for r in robots}
        self._ringout(t, dt, by_id)
        self._collision(t, by_id, contact)
        self._items(t, by_id)
        self._spawner(t, robots)
        for p in self.players:
            r = by_id.get(p.id)
            if r is not None and r.present:
                p.last_pos = r.pos.copy()
                if not contact:
                    # Während Kontakt ist die Geschwindigkeit aus geteilten Masken unbrauchbar.
                    p.last_vel = r.vel.copy()
        self._check_end(t)

    def _ringout(self, t: float, dt: float, robots: dict[int, RobotInput]) -> None:
        cfg = self.cfg
        for p in self.players:
            r = robots.get(p.id)
            if r is None or not r.present:
                # Unsichtbar heißt meist: weit draußen. Der letzte Zustand gilt weiter.
                outside = p.outside_since is not None
            else:
                outside = r.inside < 0.5
            if not outside:
                if p.outside_since is not None:
                    self._event(t, "ringout_end", player=p.id)
                p.outside_since = None
                continue
            if p.outside_since is None:
                p.outside_since = t
                self._event(t, "ringout_start", player=p.id)
            charged = min(dt, t - p.outside_since - cfg.ringout_grace_s)
            if charged > 0:
                self._damage(t, p, cfg.ringout_hp_per_s * charged, "ringout", None)

    def _collision(self, t: float, robots: dict[int, RobotInput], contact: bool) -> None:
        cfg = self.cfg
        rising = contact and not self._prev_contact
        self._prev_contact = contact
        if not rising or t - self._last_collision < cfg.collision_cooldown_s or len(self.players) != 2:
            return
        p1, p2 = self.players
        if p1.last_pos is None or p2.last_pos is None:
            return
        pos1, pos2 = p1.last_pos, p2.last_pos
        axis = pos2 - pos1
        norm = float(np.linalg.norm(axis))
        if norm < 1e-6:
            return
        axis = axis / norm
        # Nur der Anteil auf den Gegner zu zählt; Schieben ohne Anlauf soll nichts kosten.
        a = max(0.0, float(np.dot(p1.last_vel, axis)))
        b = max(0.0, float(np.dot(p2.last_vel, -axis)))
        if a + b < cfg.collision_min_speed:
            return
        self._last_collision = t
        mid = (pos1 + pos2) / 2
        if abs(a - b) <= cfg.collision_equal_ratio * max(a, b):
            self._damage(t, p1, cfg.collision_equal_damage, "collision", mid)
            self._damage(t, p2, cfg.collision_equal_damage, "collision", mid)
        elif a > b:
            self._damage(t, p2, cfg.collision_damage, "collision", mid)
        else:
            self._damage(t, p1, cfg.collision_damage, "collision", mid)

    def _items(self, t: float, robots: dict[int, RobotInput]) -> None:
        keep = []
        for item in self.items:
            if t >= item.expires:
                continue
            hit = next((r for r in robots.values() if r.present and r.outline is not None
                        and touches(r.outline, item.pos, item.radius)), None)
            if hit is None or (item.kind == "obstacle" and not item.armed(t)):
                keep.append(item)
                continue
            p = self.player(hit.id)
            if item.kind == "obstacle":
                self._damage(t, p, self.cfg.obstacle_damage, "obstacle", item.pos)
            else:
                healed = min(self.cfg.start_hp, p.hp + self.cfg.powerup_heal) - p.hp
                p.hp += healed
                self._event(t, "powerup", player=p.id, amount=round(healed, 1), pos=item.pos.tolist())
        self.items = keep

    def _spawner(self, t: float, robots: list[RobotInput]) -> None:
        cfg = self.cfg
        for kind, limit, interval in (("obstacle", cfg.obstacle_max, cfg.obstacle_interval_s),
                                      ("powerup", cfg.powerup_max, cfg.powerup_interval_s)):
            if t < self._next_spawn[kind]:
                continue
            count = sum(1 for i in self.items if i.kind == kind)
            spawned = count < limit and self.spawn(kind, t, robots)
            # Ohne freien Platz bald erneut versuchen statt ein ganzes Intervall zu warten.
            self._next_spawn[kind] = t + (self._interval(interval) if spawned or count >= limit else 1.0)

    def spawn(self, kind: str, t: float, robots: list[RobotInput]) -> bool:
        if self.finished:
            return False
        cfg = self.cfg
        obstacle = kind == "obstacle"
        radius = cfg.obstacle_radius if obstacle else cfg.powerup_radius
        margin = radius + 30
        for _ in range(80):
            pos = np.array([self.rng.uniform(margin, cfg.arena_units - margin),
                            self.rng.uniform(margin, cfg.arena_units - margin)], np.float32)
            if any(np.linalg.norm(r.pos - pos) < r.radius + radius + 120 for r in robots if r.present):
                continue
            if any(np.linalg.norm(i.pos - pos) < i.radius + radius + 60 for i in self.items):
                continue
            lifetime = cfg.obstacle_lifetime_s if obstacle else cfg.powerup_lifetime_s
            arming = cfg.obstacle_arming_s if obstacle else 0.0
            self.items.append(Item(next(self._ids), kind, pos, radius, t, t + lifetime, t + arming))
            self._event(t, "spawn", kind=kind, pos=pos.tolist())
            return True
        return False

    def _check_end(self, t: float) -> None:
        dead = [p for p in self.players if p.hp <= 0]
        if not dead:
            return
        self.finished = True
        alive = [p for p in self.players if p.hp > 0]
        self.winner = alive[0].id if alive else None
        self._event(t, "ko", players=[p.id for p in dead], winner=self.winner)
